changeSet.sql:
update sudstaff.section set name = '2' where name = '1';
update sudstaff.section set name = '1' where name = '1й участок центрального района';
ALTER TABLE sudstaff.section RENAME COLUMN name to number;
ALTER TABLE sudstaff.section ALTER COLUMN number type Integer using ( case when number = '1' then 1 when number = '2' then 2 else 1 end );
